#[path="../source_holes.rs"]mod source_holes;#[path="../owner_registry.rs"]mod owner_registry;#[path="../owner_budget.rs"]mod owner_budget;#[path="../journal.rs"]mod journal;#[path="../owner.rs"]mod owner;#[path="../face_owner.rs"]mod face_owner;#[path="../session.rs"]mod session;#[path="../vm_faces.rs"]mod vm_faces;
fn main(){let mut c=vm_faces::Controller::new().unwrap();let mut states=vec![];let initial=c.execute("shared=[]\na=native_faces.triangle(0)\nb=native_faces.triangle(1)\na.attrs['shared']=shared\nb.attrs['shared']=shared\na.attrs['non_string_keys']={17:'integer',(1,2):'tuple'}\na.attrs['tuple']=(1,2,3)\nassert a is native_faces.faces()[0] and b is native_faces.faces()[1]",20000);if let Err(vm_faces::Failure::Python(e))=&initial{for a in e.args().as_slice(){if let Some(s)=a.downcast_ref::<rustpython_vm::builtins::PyStr>(){eprintln!("native exception literal: {}",s.as_wtf8());}}}assert!(initial.unwrap());assert_eq!(c.mesh_counts(),(6,6,2));states.push(c.observe("append"));c.undo().unwrap();states.push(c.observe("undo"));assert!(!c.execute("assert native_faces.faces()==[]\nshared.append('while-undone')\nassert a.attrs['shared']==['while-undone']",20000).unwrap());states.push(c.observe("scope-mutated-while-undone"));c.redo().unwrap();states.push(c.observe("redo"));assert!(!c.execute("assert a is native_faces.faces()[0] and b is native_faces.faces()[1]\nassert a.attrs['shared'] is b.attrs['shared'] is shared\nassert a.attrs['shared']==['while-undone']\nassert type(a.attrs['tuple']) is tuple\nassert a.attrs['non_string_keys'][17]=='integer'\nassert a.attrs['non_string_keys'][(1,2)]=='tuple'\nshared.append('later')\nassert a.attrs['shared']==b.attrs['shared']==['while-undone','later']",20000).unwrap());assert_eq!(c.history_counts(),(1,0));states.push(c.observe("scope-alias-mutated"));c.undo().unwrap();let before=c.mesh_counts();let history=c.history_counts();c.set_handle_limit(Some(1));let refusal=c.execute("detached=native_faces.triangle(4)\ntry:\n    native_faces.triangle(5)\nexcept ValueError:\n    pass",20000);assert!(matches!(refusal,Err(vm_faces::Failure::Preparation(ref reason))if reason.contains("refused")));assert_eq!(c.mesh_counts(),before);assert_eq!(c.history_counts(),history);c.set_handle_limit(None);assert!(c.execute("replacement=native_faces.triangle(4)\nassert detached is not replacement\nassert native_faces.faces()[0] is replacement\nassert detached is not native_faces.faces()[0]\ndetached.attrs['held']='detached-only'\nassert 'held' not in replacement.attrs",20000).unwrap());assert_eq!(c.mesh_counts(),(3,3,1));assert_eq!(c.history_counts(),(1,0));let budget=c.budget();drop(c);assert_eq!(budget.snapshot().total(),0);println!("{}",serde_json::json!({"face_states":states,"caught_handle_admission_discards":true,"redo_preserved_on_refusal":true,"detached_ordinal_reuse_identity":true,"owner_ledger_released":true,"native_attribute_projection":false,"full_mesh_api":false,"preexisting_mutation_rollback":false,"compiler_native_wall_time_bound":false,"production_enabled":false}));}
